                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  # ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  # Phase 1: Unit tests
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  # ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  find . -name ".coverage.*" -not -name ".coveragerc" -delete
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo "─────────────────────────────────────────────────────────"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo " Phase 1/3: Unit tests under coverage"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo "─────────────────────────────────────────────────────────"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  PHASE1_START=$(date +%s)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  PYTHONPATH=. coverage run --source=data_science -m pytest \
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      data_science_tests/ -q --tb=line > "$RESULTS_DIR/unit_tests.log" 2>&1 || true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      PHASE1_END=$(date +%s)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      PHASE1_DUR=$((PHASE1_END - PHASE1_START))

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      UNIT_PASS=$(grep -oE "[0-9]+ passed" "$RESULTS_DIR/unit_tests.log" | head -1 | grep -oE "[0-9]+" || echo "0")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      UNIT_FAIL=$(grep -oE "[0-9]+ failed" "$RESULTS_DIR/unit_tests.log" | head -1 | grep -oE "[0-9]+" || echo "0")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "  Unit tests: ${UNIT_PASS} passed, ${UNIT_FAIL} failed in ${PHASE1_DUR}s"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo "${RUN_TS},unit_tests,unit,all,N/A,N/A,pytest,${UNIT_PASS},${PHASE1_DUR},N/A,N/A,$( [ "$UNIT_FAIL" = "0" ] && echo PASS || echo FAIL ),unit-tests-pass,${UNIT_FAIL}-failed" >> "$CSV_FILE"

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      # ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      # Phase 2: adk eval — pick which evals based on mode
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      # ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ADK_PATH=$(which adk)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if [ -z "$ADK_PATH" ]; then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          echo "❌ adk not in PATH — skipping eval phase"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              echo ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  echo "─────────────────────────────────────────────────────────"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      echo " Phase 2/3: adk eval under coverage"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          echo "─────────────────────────────────────────────────────────"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  # Decide which evals to run
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      case "$MODE" in
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              --full)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          EVAL_FILES=(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_01_top_channels.evalset.json:positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_02_volatility.evalset.json:positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_03_saturation.evalset.json:positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_04_peak_trough.evalset.json:positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_05_monthly_trend.evalset.json:positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "tests/eval/pos_06_blended_cpa.evalset.json:positive"
